{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Pamatolol, a structurally related phenoxypropanolamine beta-blocker, showed essentially complete absolute oral bioavailability (90.3–150.5%), supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Diacetolol, a close beta-blocker analogue with an isopropylamino side chain and polar substituents, had absolute oral bioavailability of 43% at 800 mg, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Celiprolol, the closest analogue sharing the tert-butylamino and urea-containing phenoxypropanolamine core, has oral bioavailability of 30% at 100 mg and up to 70% at higher doses, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Practolol, a related beta-blocker with a similar aryloxypropanolamine scaffold, has reported absolute oral bioavailability of 90–100%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Betaxolol, another structurally related beta-blocker, has absolute oral bioavailability of 83.9 ± 6.6%, indicating that this chemical class generally achieves high oral exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "CP-331,684, a related beta-blocker, showed a relative bioavailability of 27% from IV and oral clinical studies, still above the 20% threshold and consistent with high prediction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence from structurally related beta-blockers indicates absolute oral bioavailability well above 20% (approximately 27–100%). The closest analogue, celiprolol, has F of 30–70%. Although rifampin co-treatment can induce intestinal efflux and metabolism and may lower F, no affirmative evidence shows that the query's F would fall below 20%; therefore the prediction is high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule.",
    "No direct experimental data for the query under rifampin co-treatment; the magnitude of any rifampin-mediated reduction is unknown.",
    "Dose-dependent bioavailability observed for celiprolol introduces uncertainty in extrapolating the exact F value."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C04"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "celiprolol-like beta-blockers"
    },
    {
      "applicability": "high",
      "card_ids": ["C34"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "phenoxypropanolamine beta-blockers"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C28"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "aryloxypropanolamine beta-blockers"
    }
  ],
  "revision_action": "initial"
}

